name: Set Pay attention label for ignored issues
on:
  schedule:
    - cron: '0 10 * * 1-5'

jobs:
  set-label-for-issues:
    runs-on: ubuntu-latest
    steps:
      - name: Set Pay attention label for ignored issues
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.DEVTOOLS_GITHUB_TOKEN }}
          script: |
            const issuesList = await github.rest.issues.listForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo,
            })
            if (issuesList.data && issuesList.status === 200) {
              for (const issue of issuesList.data) {
                const createdDaysDelta = (new Date() - new Date(issue.created_at)) / (1000 * 60 * 60 * 24);

                if (!issue.labels.length && (
                  (!issue.pull_request && createdDaysDelta > 2) || (issue.pull_request && createdDaysDelta > 7)
                )) {
                  await github.rest.issues.addLabels({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    issue_number: issue.number,
                    labels: ['pay attention']
                  });
                }
              }
            }

const path = require('path');

module.exports = {
  root: true,
  extends: ['plugin:@vkontakte/eslint-plugin/typescript', 'plugin:import/recommended', 'prettier'],
  overrides: [
    {
      files: '**/*.{ts,tsx}',
      parserOptions: {
        project: path.join(__dirname, 'tsconfig.json'),
      },
    },
  ],
  rules: {
    'import/named': 'off',
    'import/no-unresolved': 'off',
    'no-shadow': 'off',
    'guard-for-in': 'off',
    '@typescript-eslint/ban-types': 'off',
    '@typescript-eslint/array-type': 'off',
    '@typescript-eslint/prefer-readonly': 'off',
    '@typescript-eslint/no-magic-numbers': 'off',
    '@typescript-eslint/no-extraneous-class': 'off',
    '@typescript-eslint/no-floating-promises': 'off',
    '@typescript-eslint/no-non-null-assertion': 'off',
    '@typescript-eslint/consistent-type-assertions': 'off',
    '@typescript-eslint/explicit-member-accessibility': 'off',
  },
};

#!/usr/bin/env node

import path from 'node:path';

import { getLang, getProjectName, getTemplate, getDirectoryName } from './prompts';
import { pipePrompts, buildConfigFromCLIArgs, copyTemplate, showCopySuccessInfo } from './helpers';

async function createVkMiniApp() {
  const initialConfig = buildConfigFromCLIArgs();
  const currentWorkingDir = process.cwd();

  const templateConfig = await pipePrompts(
    getDirectoryName,
    getProjectName,
    getLang,
    getTemplate,
  )(initialConfig);

  if (!templateConfig) return;
  const projectRoot = path.join(currentWorkingDir, templateConfig.directoryName);

  copyTemplate(templateConfig, projectRoot);
  showCopySuccessInfo(projectRoot);
}

createVkMiniApp();

import prompts from 'prompts';

export type Config = prompts.Answers<'directoryName' | 'projectName' | 'lang' | 'template'>;
export type PromptFunction = (config: Config) => Promise<Config>;

export enum LANG {
  typescript = 'typescript',
  javascript = 'javascript',
}

import chalk from 'chalk';
import { LANG } from './types';

export const LANGS = [
  {
    name: LANG.typescript,
    display: 'TypeScript',
    color: chalk.hex('#c7c7c7'),
  },
  {
    name: LANG.javascript,
    display: 'JavaScript',
    color: chalk.hex('#c7c7c7'),
  },
];

export const TEMPLATES_OPTIONS = {
  'vkui-bridge-router': {
    display: 'VKUI + Bridge + Router (recommended)',
    color: chalk.hex('#c7c7c7').bold,
    defaultValue: true,
  },
  'vkui-bridge': {
    display: 'VKUI + Bridge',
    color: chalk.hex('#c7c7c7'),
  },
  'default': {
    display: undefined,
    color: chalk.hex('#c7c7c7'),
  },
};

export const DEFAULT_DIR_NAME = 'mini-app';
export const DEFAULT_TEMPLATE_NAME = 'vkui-bridge-router';
